12	// SetIssueStatus applies lifecycle timestamps and close metadata as one Issue
13	// record update.
14	func (core *Core) SetIssueStatus(ctx context.Context, id model.ID, status model.Status, reason string) (model.Issue, error) {
15		if !model.ValidStatus(status) {
16			return model.Issue{}, fmt.Errorf("%w: invalid Issue status %q", model.ErrInvalid, status)
17		}
18		var changed model.Issue
19		err := core.store.WithTx(ctx, func(ctx context.Context, tx *store.Tx) error {
20			current, err := tx.Issue(ctx, id)
21			if err != nil {
22				return err
23			}
24			if current.Tombstone == model.Tombstoned {
25				return fmt.Errorf("%w: Issue %s is tombstoned", model.ErrConflict, id)
26			}
27			if current.Status == status && (status != model.StatusClosed || stringValue(current.CloseReason) == reason) {
28				changed = current
29				return nil
30			}
31			observed := current.Revision
32			next, err := observed.Next(core.replica)
33			if err != nil {
34				return err
35			}
36			stamp := core.timestamp()
37			current.Status = status
38			current.UpdatedAt = stamp
39			current.Revision = next
40			switch status {
41			case model.StatusOpen:
42				current.ClosedAt = nil
43				current.CloseReason = nil
44			case model.StatusInProgress:
45				if current.StartedAt == nil {
46					current.StartedAt = &stamp
47				}
48				current.ClosedAt = nil
49				current.CloseReason = nil
50			case model.StatusClosed:
51				current.ClosedAt = &stamp
52				if reason == "" {
53					current.CloseReason = nil
54				} else {
55					current.CloseReason = &reason
56				}
57			}
58			if err := tx.UpdateIssue(ctx, current, observed); err != nil {
59				return err
60			}
61			changed = current
62			return nil
63		})
64		if err == nil {
65			core.emitWarnings(model.RecordIssue, string(id), []textField{{"close_reason", stringValue(changed.CloseReason)}})
66		}
67		return changed, err
68	}
