74	func (core *Core) ClaimIssue(ctx context.Context, id model.ID, assignee string) (model.Issue, error) {
75		if assignee == "" {
76			return model.Issue{}, fmt.Errorf("%w: empty assignee", model.ErrInvalid)
77		}
