81			if err != nil {
82				return err
83			}
84			if current.Tombstone == model.Tombstoned {
85				return fmt.Errorf("%w: Issue %s is tombstoned", model.ErrConflict, id)
86			}
87			if current.Assignee != nil && *current.Assignee != "" {
88				return fmt.Errorf("%w: Issue %s is already claimed by %s", model.ErrConflict, id, *current.Assignee)
89			}
90			observed := current.Revision
91			next, err := observed.Next(core.replica)
92			if err != nil {
93				return err
94			}
95			current.Assignee, current.UpdatedAt, current.Revision = &assignee, core.timestamp(), next
96			if err := tx.UpdateIssue(ctx, current, observed); err != nil {
97				return err
98			}
99			changed = current
100			return nil
101		})
102		return changed, err
